import torch


def _resolve_dtype(dtype):
    if isinstance(dtype, str):
        return getattr(torch, dtype.replace("torch.", ""))
    return dtype


def gen_inputs(ctx, device):
    shape = tuple(ctx["self__shape"])
    dtype = _resolve_dtype(ctx["self__dtype"])
    n = 1
    for s in shape:
        n *= s
    inp = torch.randn(shape, dtype=dtype, device=device)
    mask = torch.rand(shape, device=device) > 0.3
    indices = torch.randint(0, max(n, 1), shape, device=device)
    return {"self": inp, "mask": mask, "indices": indices}


def run(self, mask, indices, fill):
    return torch._unsafe_masked_index(self, mask, [indices], fill)
